# [HELPER] translation_models.py – Define local request, response, and normalization helpers for General Text Translation\n# Uses DeepL API (concrete provider)\nimport json\nfrom typing import Any, Dict, List\n\n# Provider‑specific signal (model identifier is implicit in DeepL's service)\nDEEPL_TARGET_LANGUAGES = {\n    'EN', 'FR', 'DE', 'ES', 'PT', 'IT', 'NL', 'PL', 'RU', 'JA', 'ZH', 'KO', 'SV', 'DA', 'NO', 'FI', 'HU', 'TR', 'AR', 'TH', 'VI', 'HI', 'BG', 'RO', 'UK', 'CS', 'SK', 'SL', 'ET', 'LV', 'LT', 'HR', 'SR', 'BS'\n}\n\n# Normalized response model (internal representation)\nResponse = Dict[str, Any]\n\n# Helper to normalize DeepL's raw response into a consistent internal schema\ndef normalize_translate_response(raw: Dict[str, Any]) -> Dict[str, Any]:\n    \"\"\"Convert DeepL translation payload to a normalized response.\n\n    The normalized schema:\n    {\n        \"source\": str,\n        \"target\": str,\n        \"translated_text\": str,\n        \"segments\": List[Dict[str, Any]],\n    }\n    \"\"\"\n    # DeepL's /translate returns {'translations': [...]} where each entry contains:\n    # 'text', 'detect_source_language' (optional), 'quality' (optional)\n    raw_translations = raw.get('translations', [])\n    # For simplicity we wrap the single translation in a list\n    normalized = []\n    for entry in raw_translations:\n        normalized.append({\n            'source': entry.get('source'),\n            'target': entry.get('target_lang'),\n            'translated_text': entry.get('text'),\n            'segments': [\n                {\n                    'text': entry.get('text'),\n                    'quality': entry.get('quality'),\n                }\n            ],\n        })\n    return {'translations': normalized}\n\n# Helper to validate that requested language is supported\ndef assert_language_supported(lang_code: str) -> None:\n    if lang_code not in DEEPL_TARGET_LANGUAGES:\n        raise ValueError(f\"DeepL does not support target language '{lang_code}'\")\n\n# Example usage (for local testing)\nif __name__ == '__main__':\n    sample_raw = {\n        'translations': [\n            {'text': 'Hello world', 'target_lang': 'EN'},\n        ],\n    }\n    print('Normalized:', json.dumps(normalize_translate_response(sample_raw), indent=2))